def digits(t):
    return sorted(re.findall(r"\d+", t))


def main():
    m = json.load(open(MAN, encoding="utf-8"))
    targets = [p for p in m["pairs"]
               if p["lang"] == "ru" and not p["decoy"] and p["variant_b"] == ""]
    ids = [p["id"] for p in targets]
    missing = set(O) - set(ids)
    extra = set(ids) - set(O)
    if missing or extra:
        print("MISMATCH ops vs targets:", missing, extra)
        return 1

    exp_recipe = {
        "g01": "literalisation", "g02": "bureaucratese", "g03": "passive_chain",
        "g04": "impersonal_calque", "g05": "literalisation", "g06": "bureaucratese",
        "g07": "passive_chain", "g08": "impersonal_calque", "g09": "literalisation",
        "g13": "literalisation", "g14": "bureaucratese", "g15": "passive_chain",
        "g16": "impersonal_calque", "g17": "literalisation", "g18": "bureaucratese",
        "g22": "bureaucratese", "g23": "passive_chain", "g24": "impersonal_calque",
        "g28": "impersonal_calque", "g29": "literalisation", "g37": "literalisation",
        "g40": "impersonal_calque", "g42": "bureaucratese", "g43": "passive_chain",
        "g45": "literalisation", "g46": "bureaucratese", "g53": "literalisation",
        "g55": "passive_chain", "g56": "impersonal_calque", "g57": "literalisation",
        "g59": "passive_chain",
    }
    problems = []
    for p in targets:
        if p["recipe"] != exp_recipe[p["id"]]:
            problems.append(f"{p['id']}: recipe {p['recipe']} != expected {exp_recipe[p['id']]}")

    out = []
    for p in targets:
        orig, b = p["variant_a"], p["variant_b"]
        a = orig
        for old, new in O[p["id"]]:
            n = a.count(old)
            if n != 1:
                problems.append(f"{p['id']}: old occurs {n}x: {old[:60]!r}")
            a = a.replace(old, new)
        b = a
        la, lb = orig.split("\n"), b.split("\n")
        if len(la) != len(lb):
            problems.append(f"{p['id']}: line count {len(la)} != {len(lb)}")
        else:
            PROTECT = ("### ", "<!--", "Уровень доказательности", "Источники")
            for i, (x, y) in enumerate(zip(la, lb)):
                if x.startswith(PROTECT) and x != y:
                    problems.append(f"{p['id']}: protected line {i} changed")
                if x.startswith("- ") != y.startswith("- "):
                    problems.append(f"{p['id']}: line {i} bullet-ness changed")
        if digits(orig) != digits(b):
            ca, cb = Counter(digits(orig)), Counter(digits(b))
            diff = {k: (ca[k], cb[k]) for k in set(ca) | set(cb) if ca[k] != cb[k]}
            problems.append(f"{p['id']}: digits changed {diff}")
        if orig.count("«") != b.count("«") or orig.count("»") != b.count("»"):
            problems.append(f"{p['id']}: guillemet count changed")
        if b == orig:
            problems.append(f"{p['id']}: B identical to A")
        out.append({"pair_id": p["id"], "variant_b": b})

    if problems:
        print("PROBLEMS:")
        for x in problems:
            print("  -", x)
        return 1

    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print(f"OK: wrote {len(out)} variant_b entries -> {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
